using System.Security.Cryptography;
using System.Text;

namespace Api.Infrastructure.Auth;

/// <summary>
/// Playdex app keys (integrations of type 'api'): generated by the server, shown to the user once and stored only as
/// a SHA-256 hash, which is all capture and <see cref="ApiKeyAuthenticationHandler"/> need to recognise one. The key
/// is 128 random bits, so the hash needs no salt.
/// </summary>
public static class PlaydexAppKeys
{
    public const string HashPrefix = "sha256:";

    public static string Generate() => "plx_" + Convert.ToHexStringLower(RandomNumberGenerator.GetBytes(16));

    /// <summary>What integrations.api_key holds for <paramref name="key"/>; HashPlaydexAppKeysMigration computes the same in SQL.</summary>
    public static string Hash(string key) => HashPrefix + Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(key)));
}
